/// <summary>
/// Extension of table <c>CustConfirmTrans</c>.
/// </summary>
[ExtensionOf(tableStr(CustConfirmTrans))]
final class METCustConfirmTransTbl_Extension
{
}

Method.Source:
    /// <summary>
    /// Inserts record..
    /// </summary>
    public void insert()
    {
        next insert();
        
        /*Bug 303867 - CB232-Manage Product Changes - "Item Unavailability Reason" is not updated automatically - start*/
        if (this.METReasonId && this.ConfirmId)
        {
            METSalesLine metSalesLine;

            metSalesLine = this.salesLine().metSalesLine();

            if (metSalesLine && metSalesLine.ReasonId != this.METReasonId)
            {
                ttsbegin;
                metSalesLine.selectForUpdate(true);
                metSalesLine.skipBusinessEvents(true);
                metSalesLine.ReasonId = this.METReasonId;
                metSalesLine.DualWriteRequired = NoYes::Yes;
                metSalesLine.update();
                ttscommit;
            }
        }
        /*Bug 303867 - CB232-Manage Product Changes - "Item Unavailability Reason" is not updated automatically - end*/
    }

    /// <summary>
    /// Initializes <c>CustConfirmTrans</c> from <c>SalesLine</c>.
    /// </summary>
    /// <param name = "_salesLine"><c>SalesLine</c>.</param>
    void  initFromSalesLine(SalesLine _salesLine)
    {
        next initFromSalesLine(_salesLine);

		//CB175-SalesConfirmation - start
        this.METSalesLineQtyOrdered = _salesLine.QtyOrdered;

        METSalesLine metSalesLine;

        select firstonly Indicators, ReasonId, RecId from metSalesLine
            where metSalesLine.SalesLine == _salesLine.RecId;

        if (metSalesLine.RecId)
        {
            this.METIndicators      = metsalesLine.Indicators;
            this.METReasonId        = metsalesLine.ReasonId;
            this.METCustAvailDate   = METInventItemOrderSetup::findByItemAndSite(_salesLine.itemId, _salesLine.inventDim().InventSiteId).CustAvailDate;
        }
        
        METLegalEntityType metLegalEntityType = CompanyInfo::find().METLegalEntityType;

        
        METOrderExtractStatus extractionStatus = _salesLine.salesTable().METOrderExtractStatus;

        if (metLegalEntityType == METLegalEntityType::Food && _salesLine)
        {
            this.METSuppliedQty            = _salesline.pickedInTotalSalesUnit() + _salesline.deliveredInTotal();
        }
        else if (metLegalEntityType == METLegalEntityType::Liquor && _salesLine)
        {
            boolean isFoodSOLineItemInLiquorEntity = _salesLine.determineSuppliedQtyForSOConfirmation(metLegalEntityType);
            if (!isFoodSOLineItemInLiquorEntity)
            {
                this.setSuppliedQtyBasedOnExtractionStatus(extractionStatus, _salesLine);
            }
            else
            {
                this.METSuppliedQty = _salesLine.SalesQty;
            }

            this.METPickedCases = _salesLine.metDisplayPickedCases();
            this.METPickedBrokenCases = _salesLine.metDisplayPickedBrokenCases();
        }

        if (!_salesLine.BarCode)
        {
            this.updateSalesLineBarcodeIfEmpty(_salesLine);
        }
        //CB175-SalesConfirmation - end

        //CB232_AutoSettingItemStockStatus.
        // Added condition to check extraction status before setting the reason code. BUG 
        if (extractionStatus == METOrderExtractStatus::Extracted)
        {
            this.metSetReasonId(_salesLine);
        }
    }

    /// <summary>
    /// CB232_AutoSettingItemStockStatus.
    /// Sets reason Id field.
    /// </summary>
    /// <param name = "_salesLine"><c>SalesLine</c>.</param>
    private void metSetReasonId(SalesLine _salesLine)
    {
        METInventItemOrderSetup     itemOrderSetup;
        EcoResProductLifecycleState productLifeCycleState;
        InventDim                   inventDim;
        InventQty                   qtyOrdered,
                                    qtySupplied, 
                                    qtyLeft;

        qtyOrdered  = _salesLine.QtyOrdered;
        qtySupplied = this.metGetTotalSuppliedQty(_salesLine.InventTransId);
        qtyLeft     = qtyOrdered - qtySupplied;

        if (this.METReasonId || qtyLeft == 0)
        {
            return;
        }
        
        if (qtyLeft > 0)
        {
            // Bug 356021: CB232 - SO confirmation status of "TOS" mistakenly set for CW items
            // Exclude CW items from the auto-setting of reason code.
            boolean isCWItem = PdsCatchWeightItem::exist(_salesLine.ItemId);

            if (isCWItem)
            {
                return;
            }

            inventDim       = _salesLine.inventDim();
            itemOrderSetup  = METInventItemOrderSetup::findByItemAndSite(_salesLine.ItemId, inventDim.InventSiteId);

            if (itemOrderSetup)
            {
                productLifeCycleState = itemOrderSetup.ecoResProductLifecycleState();
  
                if (productLifeCycleState.METStatus == METEcoResProductLifecycleStateStatus::Recall)
                {
                    this.METReasonId = enum2Str(METEcoResProductLifecycleStateStatus::Recall);
                    return;
                }

                if (itemOrderSetup.ItemStatus == METConstants::ItemStatusPackChange)
                {
                    this.METReasonId = itemOrderSetup.ItemStatus;
                    return;
                }

                if (productLifeCycleState.METStatus == METEcoResProductLifecycleStateStatus::LTNA)
                {
                    this.METReasonId = enum2Str(METEcoResProductLifecycleStateStatus::LTNA);
                }
                else
                {
                    if (itemOrderSetup.StockAvailDate != dateNull())
                    {
                        TransDate today = DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone());
                        
                        if (itemOrderSetup.StockAvailDate < today)
                        {
                            this.METReasonId = METConstants::TNA;
                        }
                        else if (itemOrderSetup.StockAvailDate > today)
                        {
                            this.METReasonId = METConstants::TOS;
                        }
                    }
                }
            }

            // If the reason code is blank,
            // and Sales order confirmation line -> ‘Quantity ordered’ minus ‘Supplied quantity’ is greater than 0,
            // but you cannot meet any of the existing criteria. In that case set reason code to 'TOS'.
            if (!this.METReasonId)
            {
                this.METReasonId = METConstants::TOS;
            }
        }
    }

    /// <summary>
    /// CB232_AutoSettingItemStockStatus.
    /// Gets total supplied/picked qty per salesline.
    /// </summary>
    /// <param name = "_inventTrans"><c>InventTrans</c>.</param>
    /// <returns>Total supplied/picked qty.</returns>
    private InventQty metGetTotalSuppliedQty(InventTransId _inventTrans)
    {
        InventTransOrigin inventTransOrigin;
        InventTrans       inventTrans;

        select sum(Qty) from inventTrans
            where inventTrans.StatusIssue == StatusIssue::Picked
            exists join inventTransOrigin
                where inventTransOrigin.RecId == inventTrans.InventTransOrigin
                &&    inventTransOrigin.InventTransId == _inventTrans;

        return abs(inventTrans.Qty);
    }

    /// <summary>
    /// CB175-SalesConfirmation
    /// Update sales lines barcode if found empty
    /// </summary>
    /// <param name = "_salesLine">Salesline</param>
    private void updateSalesLineBarcodeIfEmpty(SalesLine _salesLine)
    {
        ReqItemTable reqItemTable;
        InventDim    inventDim;

        select firstonly CovInventDimId, RecId
            from reqItemTable
                where reqItemTable.ItemId == _salesLine.ItemId
                && reqItemTable.VendId != ''
                   exists join RecId from inventDim
                        where inventDim.inventDimId == reqItemTable.CovInventDimId
                        && inventDim.InventLocationId == _salesLine.inventDim().InventLocationId;
                
        if (reqItemTable.RecId && inventDim.RecId)
        {
            InventItemBarcode inventItemBarcode;

            select firstonly ItemBarCode
                from inventItemBarcode
                    where inventItemBarcode.itemId == _salesLine.ItemId
                    && inventItemBarcode.UnitID == _salesLine.SalesUnit
                    && inventItemBarcode.METVendAccount == _salesLine.CustAccount
                    && inventItemBarcode.METDefault == NoYes::Yes;

            ttsbegin;
            _salesLine.selectForUpdate(true);
            _salesLine.BarCode = inventItemBarcode.itemBarCode;
            _salesLine.update();
            ttscommit;
        }
		
      
    }

/// <summary>
/// Set supplierqty based on extraction status
/// </summary>
/// <param name = "_extractionStatus">Extraction status</param>
/// <param name = "_salesline">salesline buffer</param>
private void setSuppliedQtyBasedOnExtractionStatus(METOrderExtractStatus _extractionStatus, SalesLine _salesLine)
{
    if (_extractionStatus == METOrderExtractStatus::Extracted)
    {
        this.METSuppliedQty            = _salesline.pickedInTotalSalesUnit();
    }
    else
    {
        this.METSuppliedQty            = _salesline.reservedPhysicalInSalesUnit();
    }
}
